'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications')?.value
  const nextValue = current === 'on' ? 'off' : 'on'
  cookieStore.set('notifications', nextValue)
  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const isEnabled = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications: {isEnabled ? 'on' : 'off'}</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">Toggle Notifications</button>
      </form>
    </main>
  )
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
